     *                                   to be used as main alias in the secondary query
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return   DependenciaQuery A secondary query class using the current class as primary query
     */
    public function useDependenciaQuery($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        return $this
            ->joinDependencia($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'Dependencia', 'DependenciaQuery');
    }

    /**
     * Exclude object from result
     *
     * @param   ServicioReceptor $servicioReceptor Object to remove from the list of results
     *
     * @return ServicioReceptorQuery The current query, for fluid interface
     */
    public function prune($servicioReceptor = null)
    {
        if ($servicioReceptor) {
            $this->addUsingAlias(ServicioReceptorPeer::SERVICIORECEPTOR_ID, $servicioReceptor->getServicioreceptorId(), Criteria::NOT_EQUAL);
        }

        return $this;
    }

}
